\title{Tropical Spectral Cryptanalysis and Strong Divisibility:\\
The Eigenvalue Leak of Min-Plus Diffie--Hellman}
\author{Aristotle}
\date{2026-06-20}

\begin{document}
\maketitle

\begin{abstract}
We analyze the security of key-exchange protocols built on \emph{tropical
(min-plus) matrix powering}, and prove that the underlying \emph{Tropical Discrete
Logarithm Problem} (TDLP) admits a complete, deterministic break for almost every
key via a spectral side channel. The core mechanism is the additivity of the
tropical eigenvalue under powering: if $(\lambda,v)$ is a tropical eigenpair of a
matrix $A$, then the per-coordinate residual of the public power $A^{\otimes t}$
equals $t\lambda$ at every coordinate, so the secret exponent $t$ is recovered by a
single division whenever $\lambda \neq 0$. We then upgrade this from a value-recovery
attack to a \emph{structural} one. Viewing the leaked eigenvalue as a function of the
genuine exponent, $t \mapsto c\,t$ with $c = \lambda(A)$, we show this sequence is a
\emph{strong divisibility sequence}: $\gcd(cm, cn) = c\,\gcd(m,n)$. Consequently the
public transcript leaks the entire divisibility lattice of the secret exponent:
$(m+1)\mid(k+1) \iff c(m+1)\mid c(k+1)$. We further show the Diffie--Hellman shared
key's eigenvalue factorizes through public data,
$c\cdot\lambda(\text{shared}) = \lambda(\text{pub}_a)\cdot\lambda(\text{pub}_b)$,
ruling out hardness amplification by nesting. The results form a \emph{bridge}
between tropical spectral cryptanalysis and the classical theory of strong
divisibility sequences (which also contains the Fibonacci and Mersenne sequences),
yielding a reusable security-audit criterion. All results have been formally
verified.
\end{abstract}

\section{Introduction}

The search for quantum-resistant cryptographic primitives has driven interest in
unconventional algebraic platforms. One such platform is \emph{tropical algebra},
the min-plus semiring $(\R, \min, +)$, in which the tropical matrix product encodes
the all-pairs shortest path problem and is therefore plausibly one-way: computable
in $O(n^3)$ time forward but resistant to inversion. A line of proposals adapts the
classical Diffie--Hellman key exchange by replacing modular exponentiation with
\emph{tropical matrix powering} $A^{\otimes t}$, computable in $O(n^3 \log t)$ by
repeated squaring. The security rests on the \emph{Tropical Discrete Logarithm
Problem} (TDLP): recover $t$ from $(A, A^{\otimes t})$.

This paper gives a precise, formally verified account of why such schemes fail. Our
contributions are: (1) a deterministic spectral break (Section~\ref{sec:break});
(2) a strong-divisibility upgrade exposing the full arithmetic of the secret
(Section~\ref{sec:sds}); (3) a no-amplification theorem (Section~\ref{sec:amp}); and
(4) a reusable audit criterion (Section~\ref{sec:audit}).

\section{Tropical preliminaries}

\subsection{The min-plus semiring}
The \emph{tropical semiring} is $(\R, \oplus, \otimes)$ with
\[
a \oplus b = \min(a,b), \qquad a \otimes b = a + b.
\]
Tropical addition is idempotent and lacks additive inverses; tropical multiplication
is ordinary addition, with identity $0$.

\subsection{Tropical matrices and vectors}
For $A,B \in \R^{n\times n}$ and $v \in \R^n$,
\[
(A \otimes B)_{ij} = \min_k\big(A_{ik}+B_{kj}\big), \qquad
(A \otimes v)_i = \min_k\big(A_{ik}+v_k\big).
\]
The matrix product is associative, computable in $O(n^3)$, and coincides with one
step of Floyd--Warshall relaxation.

\subsection{Tropical matrix powers}
We use a field-friendly indexing in which the index is one less than the genuine
exponent. Define
\[
\mathrm{tropMatPow}(A,0) = A, \qquad
\mathrm{tropMatPow}(A,k+1) = A \otimes \mathrm{tropMatPow}(A,k),
\]
so $\mathrm{tropMatPow}(A,k) = A^{\otimes(k+1)}$ is the genuine $(k+1)$-fold product.
The power obeys the following laws (formally verified):
\begin{itemize}
  \item \textbf{Additive:} $A^{\otimes a}\otimes A^{\otimes b} = A^{\otimes(a+b)}$.
  \item \textbf{Power-of-power:} $(A^{\otimes a})^{\otimes b} = A^{\otimes(ab)}$,
        encoding $(a+1)(b+1)-1 = ab+a+b$.
  \item \textbf{Commutation / DH correctness:}
        $(A^{\otimes a})^{\otimes b} = (A^{\otimes b})^{\otimes a}$.
\end{itemize}
By the additive law, $A^{\otimes t}$ is computed by binary exponentiation in
$O(n^3\log t)$ time, motivating the hardness assumption on its inverse.

\section{Tropical spectra and the residual side channel}

\begin{definition}[Tropical eigenpair]
A pair $(\lambda,v)\in\R\times\R^n$ is a \emph{tropical eigenpair} of $A$ when
\[
(A\otimes v)_i = v_i + \lambda \quad\text{for all } i,
\]
i.e.\ $A\otimes v = v + \lambda\one$. The scalar $\lambda$ is the \emph{tropical
eigenvalue}; for an irreducible matrix it equals the minimum cycle mean of the
associated weighted digraph.
\end{definition}

\begin{definition}[Residual]
The \emph{tropical residual} of $A$ at $v$ is $\res(A,v)_i = (A\otimes v)_i - v_i$.
\end{definition}

\begin{lemma}[Residual equals eigenvalue]\label{lem:res}
If $(\lambda,v)$ is a tropical eigenpair of $A$, then $\res(A,v)_i = \lambda$ for
every $i$.
\end{lemma}
\begin{proof}
$\res(A,v)_i = (A\otimes v)_i - v_i = (v_i+\lambda)-v_i = \lambda$.
\end{proof}

\section{The eigenvalue leak and the TDLP break}\label{sec:break}

\begin{theorem}[Eigenvalue additivity under powering]\label{thm:add}
Let $(\lambda,v)$ be a tropical eigenpair of $A$. Then for every index $k$ and
coordinate $i$,
\[
\res\big(A^{\otimes(k+1)}, v\big)_i = (k+1)\lambda.
\]
\end{theorem}
\begin{proof}[Proof sketch]
The eigenvector relation gives $A\otimes v = v + \lambda\one$. Adding a constant
commutes with the min-plus action, so $A\otimes(v+\lambda\one) = (A\otimes v) +
\lambda\one = v + 2\lambda\one$. By induction on the number of factors,
$A^{\otimes(k+1)}\otimes v = v + (k+1)\lambda\one$; subtracting $v$ coordinatewise
yields the residual $(k+1)\lambda$.
\end{proof}

\begin{corollary}[TDLP recovery]
If $\lambda = \lambda(A)\neq 0$ and a reference eigenvector $v$ is known, the secret
genuine exponent $t=k+1$ is recovered from any single coordinate by
$t = \res(A^{\otimes t}, v)_i/\lambda$, at cost one matrix--vector product and one
division.
\end{corollary}

\begin{theorem}[The silent regime]
If $(0,v)$ is a tropical eigenpair of $A$, then $\res(A^{\otimes t}, v)_i = 0$ for
all $t$ and $i$: the residual side channel leaks nothing about $t$.
\end{theorem}
\begin{proof}
Specialize Theorem~\ref{thm:add} at $\lambda=0$.
\end{proof}

These results give a sharp dichotomy: the scheme is broken precisely when
$\lambda\neq 0$ and residual-silent exactly when $\lambda=0$. A zero eigenvalue
requires a zero-weight cycle, a non-generic condition, so the break applies to almost
every key.

\section{From value leak to structural leak: strong divisibility}\label{sec:sds}

\begin{definition}[Strong divisibility sequence]
A \emph{strong divisibility sequence} (SDS) is $a:\N\to\N$ with $a(0)=0$ and
$\gcd(a(m),a(n)) = a(\gcd(m,n))$ for all $m,n$.
\end{definition}

The Fibonacci numbers, Mersenne numbers $b^n-1$, and the identity sequence are
classical examples. Two consequences of the axioms:
\begin{lemma}[Divisibility monotonicity]\label{lem:dvd}
$m\mid n \implies a(m)\mid a(n)$.
\end{lemma}
\begin{proof}
If $m\mid n$ then $\gcd(m,n)=m$, so $\gcd(a(m),a(n))=a(m)$, whence $a(m)\mid a(n)$.
\end{proof}

\begin{definition}[Tropical eigenvalue sequence]
For $c\in\N$ define $\tropEig(c)$ by $a(t)=c\,t$. As a function of the genuine
exponent $t$, this is the leaked eigenvalue $\lambda(A^{\otimes t}) = c\,t$ with
$c=\lambda(A)$.
\end{definition}

\begin{theorem}[$\tropEig(c)$ is an SDS]
$\tropEig(c)$ is a strong divisibility sequence.
\end{theorem}
\begin{proof}
$a(0)=0$, and $\gcd(cm,cn)=c\,\gcd(m,n)$ by distributivity of $\gcd$ over
multiplication, so $\gcd(a(m),a(n))=a(\gcd(m,n))$.
\end{proof}

\begin{theorem}[Residual equals sequence value]\label{thm:link}
Let $(c,v)$ be a tropical eigenpair of $A$ with $c\in\N$. Then for every index $k$
and coordinate $i$,
\[
\res\big(A^{\otimes(k+1)}, v\big)_i = \big(\tropEig(c)\big)(k+1) \in \R.
\]
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:add} the left side equals $(k+1)c$; by definition the right side
is $c(k+1)$.
\end{proof}

This identifies the \emph{physically measurable} residual with the
\emph{number-theoretic} SDS value, licensing transport of the SDS calculus onto the
cryptanalysis.

\begin{theorem}[Divisibility leak]\label{thm:leak}
For $c>0$ and all $m,k$,
\[
(m+1)\mid(k+1) \iff \big(\tropEig(c)\big)(m+1)\ \big|\ \big(\tropEig(c)\big)(k+1).
\]
\end{theorem}
\begin{proof}
($\Rightarrow$) is Lemma~\ref{lem:dvd}. ($\Leftarrow$) $c(m+1)\mid c(k+1)$; cancel
the positive factor $c$ to get $(m+1)\mid(k+1)$.
\end{proof}

\begin{remark}
Equivalence means the public leaked eigenvalues are a \emph{faithful} image of the
secret exponents' divisibility lattice: an adversary reads off relations such as
``secret $X$ divides secret $Y$'' or ``secret $X$ is prime'' directly from public
data. This is strictly stronger than the injectivity used in
Section~\ref{sec:break}.
\end{remark}

\begin{corollary}[Eigenvalue gcd identity]
$\gcd\big(\lambda(A^{\otimes m}), \lambda(A^{\otimes n})\big) =
\lambda(A^{\otimes \gcd(m,n)})$.
\end{corollary}

\section{No hardness amplification by nesting}\label{sec:amp}

\begin{theorem}[Shared-key eigenvalue factorization]\label{thm:prod}
For all $c,a,b\in\N$,
\[
c\cdot\big(\tropEig(c)\big)\big((a+1)(b+1)\big) =
\big(\tropEig(c)\big)(a+1)\cdot\big(\tropEig(c)\big)(b+1).
\]
\end{theorem}
\begin{proof}
Both sides equal $c^2(a+1)(b+1)$.
\end{proof}

Writing $\lambda(\text{shared}) = a((a+1)(b+1))$, $\lambda(\text{pub}_a)=a(a+1)$,
$\lambda(\text{pub}_b)=a(b+1)$, this reads $c\cdot\lambda(\text{shared}) =
\lambda(\text{pub}_a)\cdot\lambda(\text{pub}_b)$, with every right-hand quantity
public. Nesting multiplies a public invariant rather than concealing a private one.

\begin{theorem}[Shared-key residual]
Let $(c,v)$ be a tropical eigenpair of $A$. For all indices $a,b$ and coordinates
$i$,
\[
\res\Big(\big(A^{\otimes(a+1)}\big)^{\otimes(b+1)}, v\Big)_i =
\big(\tropEig(c)\big)\big((a+1)(b+1)\big).
\]
\end{theorem}
\begin{proof}[Proof sketch]
By the power-of-power law the nested power equals $A^{\otimes(a+1)(b+1)}$ (using
$(a+1)(b+1)\ge 1$); apply Theorem~\ref{thm:link}.
\end{proof}

\section{A reusable security-audit criterion}\label{sec:audit}

The break is forced by structure, not by an ad hoc attack. The public transcript, as
a function of the secret, is a strong divisibility sequence, and
Theorem~\ref{thm:leak} shows any such transcript leaks the secret's divisibility
lattice. This yields a falsifiable design test:
\begin{quote}
\textbf{Audit criterion.} If the public transcript of a key-exchange scheme, viewed
as a function of the secret exponent, is a strong divisibility sequence, then the
scheme is not exponent-hiding.
\end{quote}
Because the SDS framework simultaneously contains the Fibonacci, Mersenne, identity,
and tropical-eigenvalue sequences, the criterion is broadly applicable.

\section{Discussion}

A cipher's safety lives in the structure it \emph{fails} to expose. Tropical matrix
powering exposes too much: an eigenvalue that counts the secret exactly at every
coordinate, and a leaked sequence whose arithmetic is an open book. The dichotomy of
Section~\ref{sec:break} is sharp, but the silent regime ($\lambda=0$) is non-generic
and arguably useless. The structural leak of Section~\ref{sec:sds} defeats even
partial secrecy goals, and Section~\ref{sec:amp} forecloses the obvious patch. This
does not impugn tropical mathematics, only the use of min-plus powering as a
discrete-log platform.

\section{Future directions}

\textbf{C1.} \emph{The eigenvalue-leak dichotomy is exhaustive.} The scheme is
broken in polynomial time iff $\lambda\neq 0$, and leaks nothing when $\lambda=0$;
conjecturally $\lambda=0$ is the unique secure eigenvalue.

\textbf{C2.} \emph{Strong divisibility forces full lattice exposure.} Any
key-exchange whose transcript is an SDS in the secret leaks its full divisibility
lattice and is not exponent-hiding.

\textbf{C3.} \emph{Multiplicative shadow obstructs amplification.} Nesting cannot
amplify TDLP hardness because the shared-key eigenvalue factorizes through public
data.

\textbf{C4.} \emph{Generic random matrices have nonzero eigenvalue.} For a random
integer tropical matrix of size $n\ge 2$ with i.i.d.\ entries in $\{0,\dots,M\}$ and
zero self-loops, the max cycle mean is $0$ only on a vanishing-probability set; by
C1 the scheme is then broken with overwhelming probability.

\section{Conclusion}

The tropical eigenvalue is additive under powering, breaking the TDLP whenever it is
nonzero; the leaked eigenvalue sequence $t\mapsto ct$ is a strong divisibility
sequence, exposing the secret's divisibility lattice; and the shared-key eigenvalue
factorizes through public data, precluding amplification by nesting. The unifying
lesson is a security-audit criterion of independent interest: transcripts that form
strong divisibility sequences cannot hide their secrets.

