function TROP_MAT_POW(A, k):
    t <- k + 1                      # genuine exponent
    result <- undefined
    base <- A
    while t > 0:
        if t is odd:
            result <- base if result undefined else TROP_MAT_MUL(result, base)
        t <- floor(t / 2)
        if t > 0:
            base <- TROP_MAT_MUL(base, base)   # tropical squaring
    return result

function TROP_MAT_MUL(A, B):
    for i, j: (A (x) B)[i][j] <- min over k of (A[i][k] + B[k][j])
    return A (x) B

function RECONSTRUCT_DIVISIBILITY_LATTICE(eigenvalues, c):
    secrets <- [ e / c for e in eigenvalues ]
    for each pair (i, j):
        relations[(i, j)] <- (secrets[j] mod secrets[i] == 0)
    return relations
